from taf.fdsw.rc.interfaces.FDSW22A.fdsw import FDSW22A
from taf.fdsw.rc.interfaces.FDSW23B.autoconnection import AutoConfiguration23B
from taf.fdsw.rc.interfaces.FDSW23B.certs import Certificates
from taf.fdsw.rc.interfaces.FDSW23B.diagnostics import Diagnostics23B
from taf.fdsw.rc.interfaces.FDSW23B.swm import SoftwareManagement23B


class FDSW23B(FDSW22A):
    VERSION_NAME = 'FDSW23B'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW22A, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
        self.autoconnection = AutoConfiguration23B(client=self._client)
        self.swm = SoftwareManagement23B(client=self._client)
        self.diagnostics = Diagnostics23B(client=self._client)
        self.certs = Certificates(client=self._client)
